-- 1: item 1
SELECT 'Muslim Data Azkars #1 - When waking up', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #1 - When waking up' AND rt.locale_code = 'ar' AND rt.text = 'الْحَمْدُ للَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا, وَإِلَيْهِ النُّشُورُ');
SELECT r.id, 'ar', 'الْحَمْدُ للَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا, وَإِلَيْهِ النُّشُورُ' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #1 - When waking up' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'الْحَمْدُ للَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا, وَإِلَيْهِ النُّشُورُ');
SELECT r.id, 'en', 'Praise is to Allah Who gives us life after He has caused us to die and to Him is the return.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #1 - When waking up' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'Al-Bukhari, cf. Al-Asqalani, Fathul-Bari 11/113, Muslim 4/2083.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #1 - When waking up' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
SELECT r.id, 'ar', 'البخاري مع الفتح، ١١/ ١١٣، برقم ٦٣١٤، ومسلم، ٤/ ٢٠٨٣، برقم ٢٧١١.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #1 - When waking up' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

