SELECT r.id, 'ar', 'من قال ذلك غُفِرَ له، فإن دعا استجيب له، فإن قام فتوضأ ثم صلى قُبلت صلاته، البخاري مع الفتح، ٣/ ٣٩، برقم ١١٥٤، وغيره، واللفظ لابن ماجه، انظر: صحيح ابن ماجه، ٢/٣٣٥ .' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #2 - When waking up' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

