SELECT r.id, 'en', 'O Allah, place light in my heart, and on my tongue light, and in my ears light and in my sight light, and above me light, and below me light, and to my right light, and to my left light, and before me light and behind me light. Place in my soul light. Magnify for me light, and amplify for me light. Make for me light and make me a light. O Allah, grant me light, and place light in my nerves, and in my body light and in my blood light and in my hair light and in my skin light. O Allah, make for me a light in my grave... And a light in my bones. Increase me in light, increase me in light, increase me in light. Grant me light upon light.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #19 - When going to the mosque' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'Al-Bukhari 11/116 (Hadith no. 6316), Muslim 1/526 (Hadith no. 763).' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #19 - When going to the mosque' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
SELECT r.id, 'ar', 'انظر جميع هذه الألفاظ في البخاري، ١١/ ١١٦، برقم ٦٣١٦، ومسلم، ١/ ٥٢٦، و٥٢٩، و٥٣٠، برقم ٧٦٣ . الترمذي، ٥/ ٤٨٣، برقم ٣٤١٩ . أخرجه البخاري في الأدب المفرد، برقم ٦٩٥، ص٢٥٨ وصحح إسناده الألباني في صحيح الأدب المفرد، برقم ٥٣٦ . ذكره ابن حجر في فتح الباري، وعزاه إلى ابن أبي عاصم في كتاب الدعاء، انظر الفتح ١١/١١٨، وقال: فاجتمع من اختلاف الروايات خمس وعشرون خصلة.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #19 - When going to the mosque' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

