-- 19: item 20
SELECT 'Muslim Data Azkars #20 - Upon entering the mosque', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #20 - Upon entering the mosque' AND rt.locale_code = 'ar' AND rt.text = 'يَبْدَأُ بِرِجْلِهِ الْيُمْنَى, وَيَقُولُ: أَعُوذُ بِاللَّهِ العَظِيمِ, وَبِوَجْهِهِ الْكَرِيمِ, وَسُلْطَانِهِ الْقَدِيمِ, مِنَ الشَّيْطَانِ الرَّجِيمِ. [بِسْمِ اللَّهِ, وَالصَّلَاةُ] [وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ] اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ');
SELECT r.id, 'ar', 'يَبْدَأُ بِرِجْلِهِ الْيُمْنَى, وَيَقُولُ: أَعُوذُ بِاللَّهِ العَظِيمِ, وَبِوَجْهِهِ الْكَرِيمِ, وَسُلْطَانِهِ الْقَدِيمِ, مِنَ الشَّيْطَانِ الرَّجِيمِ. [بِسْمِ اللَّهِ, وَالصَّلَاةُ] [وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ] اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #20 - Upon entering the mosque' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'يَبْدَأُ بِرِجْلِهِ الْيُمْنَى, وَيَقُولُ: أَعُوذُ بِاللَّهِ العَظِيمِ, وَبِوَجْهِهِ الْكَرِيمِ, وَسُلْطَانِهِ الْقَدِيمِ, مِنَ الشَّيْطَانِ الرَّجِيمِ. [بِسْمِ اللَّهِ, وَالصَّلَاةُ] [وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ] اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ');
SELECT r.id, 'en', 'I seek refuge in Almighty Allah, by His Noble Face, by His primordial power, from Satan the outcast. In the Name of Allah, and blessings and peace be upon the Messenger of Allah. O Allah, open before me the doors of Your mercy.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #20 - Upon entering the mosque' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'Abu Dawud, Sahihul-Jami'' As-Saghir (Hadith no. 4591), Ibn As-Sunni (Hadith no. 88), Abu Dawud 1/126, Sahihul-Jami'' 1/528, Muslim 1/494, Ibn Majah 1/128-129.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #20 - Upon entering the mosque' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
SELECT r.id, 'ar', 'لقول أنس بن مالك رضي الله عنه: ((من السنة إذ دخلت المسجد أن تَبدأ برجلك اليمنى، وإذا خرجت أن تبدأ برجلك اليسرى))، أخرجه الحاكم، ١/ ٢١٨، وصححه على شرط مسلم، ووافقه الذهبي، وأخرجه البيهقي، ٢/ ٤٤٢، وحسنه الألباني في سلسلة الأحاديث الصحيحة، ٥/ ٦٢٤، برقم ٢٤٧٨. أبو داود، برقم ٤٦٦، وانظر: صحيح الجامع، برقم ٤٥٩١ . رواه ابن السني، برقم ٨٨، وحسنه الألباني في الثمر المستطاب، ص ٦٠٧. أبو داود، ١/ ١٢٦، برقم ٤٦٥، وانظر: صحيح الجامع، ١/٥٢٨ . مسلم، ١/ ٤٩٤، برقم ٧١٣، وفي سنن ابن ماجه من حديث فاطمة ’:((اللهم اغفر لي ذنوبي،وافتح لي أبواب رحمتك))، وصححه الألباني لشواهده. انظر: صحيح ابن ماجه، ١/١٢٨-١٢٩.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #20 - Upon entering the mosque' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

