-- 21: item 22
SELECT 'Muslim Data Azkars #22 - Upon hearing the athan', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #22 - Upon hearing the athan' AND rt.locale_code = 'ar' AND rt.text = 'يَقُولُ مِثْلَ مَا يَقُولُ المُؤَذِّنُ إِلاَّ فِي (حَيَّ عَلَى الصَّلَاةِ وَحَيَّ عَلَى الْفَلَاحِ) فَيقُولُ: (لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ)');
SELECT r.id, 'ar', 'يَقُولُ مِثْلَ مَا يَقُولُ المُؤَذِّنُ إِلاَّ فِي (حَيَّ عَلَى الصَّلَاةِ وَحَيَّ عَلَى الْفَلَاحِ) فَيقُولُ: (لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #22 - Upon hearing the athan' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'يَقُولُ مِثْلَ مَا يَقُولُ المُؤَذِّنُ إِلاَّ فِي (حَيَّ عَلَى الصَّلَاةِ وَحَيَّ عَلَى الْفَلَاحِ) فَيقُولُ: (لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ)');
SELECT r.id, 'en', 'Repeat what the muazzin says, except for when he says: حَيَّ عَلَى الصَّلاَةِ وَحَيَّ عَلَى الْفَلَاحِ.Here you should says: "There is no might and no power except by Allah".' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #22 - Upon hearing the athan' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'Al-Bukhari 1/152, Muslim 1/288.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #22 - Upon hearing the athan' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
SELECT r.id, 'ar', 'البخاري، ١/ ١٥٢، برقم ٦١١، ورقم ٦١٣، ومسلم، ١/ ٢٨٨، برقم ٣٨٣.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #22 - Upon hearing the athan' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

