-- 22: item 23
SELECT 'Muslim Data Azkars #23 - Upon hearing the athan', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #23 - Upon hearing the athan' AND rt.locale_code = 'ar' AND rt.text = 'يَقُولُ: وَأَنَا أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ وَأَنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ, رَضِيتُ بِاللَّهِ رَبَّاً, وَبِمُحَمَّدٍ رَسُولاً, وَبِالْإِسْلاَمِ دِينَاً. يَقُولُ ذَلِكَ عَقِبَ تَشَهُّدِ الْمُؤَذِّنِ.');
