SELECT 'Muslim Data Azkars #27 - Supplication at the start of the prayer', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #27 - Supplication at the start of the prayer' AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ, اللَّهُمَّ نَقِّنِي مِنْ خَطَايَايَ كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ, اللَّهُمَّ اغْسِلْني مِنْ خَطَايَايَ, بِالثَّلْجِ وَالْماءِ وَالْبَرَدِ');
SELECT r.id, 'ar', 'اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ, اللَّهُمَّ نَقِّنِي مِنْ خَطَايَايَ كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ, اللَّهُمَّ اغْسِلْني مِنْ خَطَايَايَ, بِالثَّلْجِ وَالْماءِ وَالْبَرَدِ' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #27 - Supplication at the start of the prayer' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ, اللَّهُمَّ نَقِّنِي مِنْ خَطَايَايَ كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ, اللَّهُمَّ اغْسِلْني مِنْ خَطَايَايَ, بِالثَّلْجِ وَالْماءِ وَالْبَرَدِ');
SELECT r.id, 'en', 'O Allah, separate me from my sins as You have separated the East from the West. O Allah, cleanse me of my transgressions as the white garment is cleansed of stains. O Allah, wash away my sins with ice and water and frost.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #27 - Supplication at the start of the prayer' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'Al-Bukhari 1/181, Muslim 1/419.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #27 - Supplication at the start of the prayer' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
