-- 28: item 29
SELECT 'Muslim Data Azkars #29 - Supplication at the start of the prayer', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #29 - Supplication at the start of the prayer' AND rt.locale_code = 'ar' AND rt.text = 'وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَوَاتِ وَالأَرْضَ حَنِيفَاً وَمَا أَنَا مِنَ الْمُشْرِكِينَ, إِنَّ صَلاَتِي, وَنُسُكِي, وَمَحْيَايَ, وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ, لاَ شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ. اللَّهُمَّ أَنْتَ المَلِكُ لاَ إِلَهَ إِلاَّ أَنْتَ, أَنْتَ رَبِّي وَأَنَا عَبْدُكَ, ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبي جَمِيعَاً إِنَّهُ لاَ يَغْفِرُ الذُّنوبَ إِلاَّ أَنْتَ. وَاهْدِنِي لِأَحْسَنِ الأَخْلاقِ لاَ يَهْدِي لِأَحْسَنِها إِلاَّ أَنْتَ, وَاصْرِفْ عَنِّي سَيِّئَهَا, لاَ يَصْرِفُ عَنِّي سَيِّئَهَا إِلاَّ أَنْتَ, لَبَّيْكَ وَسَعْدَيْكَ, وَالخَيْرُ كُلُّهُ بِيَدَيْكَ, وَالشَّرُّ لَيْسَ إِلَيْكَ, أَنَا بِكَ وَإِلَيْكَ, تَبارَكْتَ وَتَعَالَيْتَ, أَسْتَغْفِرُكَ وَأَتوبُ إِلَيْكَ');
SELECT r.id, 'ar', 'وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَوَاتِ وَالأَرْضَ حَنِيفَاً وَمَا أَنَا مِنَ الْمُشْرِكِينَ, إِنَّ صَلاَتِي, وَنُسُكِي, وَمَحْيَايَ, وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ, لاَ شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ. اللَّهُمَّ أَنْتَ المَلِكُ لاَ إِلَهَ إِلاَّ أَنْتَ, أَنْتَ رَبِّي وَأَنَا عَبْدُكَ, ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبي جَمِيعَاً إِنَّهُ لاَ يَغْفِرُ الذُّنوبَ إِلاَّ أَنْتَ. وَاهْدِنِي لِأَحْسَنِ الأَخْلاقِ لاَ يَهْدِي لِأَحْسَنِها إِلاَّ أَنْتَ, وَاصْرِفْ عَنِّي سَيِّئَهَا, لاَ يَصْرِفُ عَنِّي سَيِّئَهَا إِلاَّ أَنْتَ, لَبَّيْكَ وَسَعْدَيْكَ, وَالخَيْرُ كُلُّهُ بِيَدَيْكَ, وَالشَّرُّ لَيْسَ إِلَيْكَ, أَنَا بِكَ وَإِلَيْكَ, تَبارَكْتَ وَتَعَالَيْتَ, أَسْتَغْفِرُكَ وَأَتوبُ إِلَيْكَ' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #29 - Supplication at the start of the prayer' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَوَاتِ وَالأَرْضَ حَنِيفَاً وَمَا أَنَا مِنَ الْمُشْرِكِينَ, إِنَّ صَلاَتِي, وَنُسُكِي, وَمَحْيَايَ, وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ, لاَ شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ. اللَّهُمَّ أَنْتَ المَلِكُ لاَ إِلَهَ إِلاَّ أَنْتَ, أَنْتَ رَبِّي وَأَنَا عَبْدُكَ, ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبي جَمِيعَاً إِنَّهُ لاَ يَغْفِرُ الذُّنوبَ إِلاَّ أَنْتَ. وَاهْدِنِي لِأَحْسَنِ الأَخْلاقِ لاَ يَهْدِي لِأَحْسَنِها إِلاَّ أَنْتَ, وَاصْرِفْ عَنِّي سَيِّئَهَا, لاَ يَصْرِفُ عَنِّي سَيِّئَهَا إِلاَّ أَنْتَ, لَبَّيْكَ وَسَعْدَيْكَ, وَالخَيْرُ كُلُّهُ بِيَدَيْكَ, وَالشَّرُّ لَيْسَ إِلَيْكَ, أَنَا بِكَ وَإِلَيْكَ, تَبارَكْتَ وَتَعَالَيْتَ, أَسْتَغْفِرُكَ وَأَتوبُ إِلَيْكَ');
SELECT r.id, 'en', 'I have turned my face sincerely towards He who has brought forth the heavens and the Earth and I am not of those who associate (others with Allah). Indeed my prayer, my sacrifice, my life and my death are for Allah, Lord of the worlds, no partner has He, with this I am commanded and I am of the Muslims. O Allah, You are the Sovereign, none has the right to be worshiped except You. You are my Lord and I am Your servant, I have wronged my own soul and have acknowledged my sin, so forgive me all my sins for no one forgives sins except You. Guide me to the best of characters for none can guide to it other than You, and deliver me from the worst of characters for none can deliver me from it other than You. Here I am, in answer to Your call, happy to serve you. All good is within Your hands and evil does not stem from You. I exist by your will and will return to you. Blessed and High are You, I seek Your forgiveness and repent unto You.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #29 - Supplication at the start of the prayer' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'Muslim 1/534' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #29 - Supplication at the start of the prayer' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
SELECT r.id, 'ar', 'أخرجه مسلم، ١/ ٥٣٤، برقم ٧٧١.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #29 - Supplication at the start of the prayer' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

