-- 29: item 30
SELECT 'Muslim Data Azkars #30 - Supplication at the start of the prayer', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #30 - Supplication at the start of the prayer' AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُمَّ رَبَّ جِبْرَائِيلَ, وَمِيْكَائِيلَ, وَإِسْرَافِيلَ, فَاطِرَ السَّمَوَاتِ وَالأَرْضِ, عَالِمَ الغَيْبِ وَالشَّهَادَةِ أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ. اهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقيمٍ');
SELECT r.id, 'ar', 'اللَّهُمَّ رَبَّ جِبْرَائِيلَ, وَمِيْكَائِيلَ, وَإِسْرَافِيلَ, فَاطِرَ السَّمَوَاتِ وَالأَرْضِ, عَالِمَ الغَيْبِ وَالشَّهَادَةِ أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ. اهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقيمٍ' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #30 - Supplication at the start of the prayer' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُمَّ رَبَّ جِبْرَائِيلَ, وَمِيْكَائِيلَ, وَإِسْرَافِيلَ, فَاطِرَ السَّمَوَاتِ وَالأَرْضِ, عَالِمَ الغَيْبِ وَالشَّهَادَةِ أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ. اهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقيمٍ');
SELECT r.id, 'en', 'O Allah, Lord of Jibraeel, Meekaeel and Israfeel (great angles), Creator of the heavens and the Earth, Knower of the seen and the unseen. You are the arbitrator between Your servants in that which they have disputed. Guide me to the truth by Your leave, in that which they have differed, for verily You guide whom You will to a straight path.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #30 - Supplication at the start of the prayer' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'Muslim 1/534' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #30 - Supplication at the start of the prayer' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
SELECT r.id, 'ar', 'أخرجه مسلم، ١/ ٥٣٤، برقم ٧٧٠ .' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #30 - Supplication at the start of the prayer' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

