-- 30: item 31
SELECT 'Muslim Data Azkars #31 - Supplication at the start of the prayer', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #31 - Supplication at the start of the prayer' AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُ أَكْبَرُ كَبِيرَاً, اللَّهُ أَكْبَرُ كَبِيراً, اللَّهُ أَكْبَرُ كَبِيراً, وَالْحَمْدُ لِلَّهِ كَثيراً, وَالْحَمْدُ لِلَّهِ كَثيراً, وَالْحَمْدُ لِلَّهِ كَثيراً, وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلاً (ثَلاثاً) أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ: مِنْ نَفْخِهِ, وَنَفْثِهِ, وَهَمْزِهِ');
SELECT r.id, 'ar', 'اللَّهُ أَكْبَرُ كَبِيرَاً, اللَّهُ أَكْبَرُ كَبِيراً, اللَّهُ أَكْبَرُ كَبِيراً, وَالْحَمْدُ لِلَّهِ كَثيراً, وَالْحَمْدُ لِلَّهِ كَثيراً, وَالْحَمْدُ لِلَّهِ كَثيراً, وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلاً (ثَلاثاً) أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ: مِنْ نَفْخِهِ, وَنَفْثِهِ, وَهَمْزِهِ' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #31 - Supplication at the start of the prayer' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُ أَكْبَرُ كَبِيرَاً, اللَّهُ أَكْبَرُ كَبِيراً, اللَّهُ أَكْبَرُ كَبِيراً, وَالْحَمْدُ لِلَّهِ كَثيراً, وَالْحَمْدُ لِلَّهِ كَثيراً, وَالْحَمْدُ لِلَّهِ كَثيراً, وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلاً (ثَلاثاً) أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ: مِنْ نَفْخِهِ, وَنَفْثِهِ, وَهَمْزِهِ');
SELECT r.id, 'en', 'Allah is the Greatest, Most Great. Allah is the Greatest, Most Great. Allah is the Greatest, Most Great. Praise is to Allah, abundantly. Praise is to Allah, abundantly. Praise is to Allah, abundantly. Glory is to Allah, at the break of day and at its end. (Three times)(1)I seek refuge in Allah from Satan. From his breath and from his voice and from his whisper.(2)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #31 - Supplication at the start of the prayer' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'Abu Dawud 1/203, Ibn Majah 1/265, Ahmad 4/85. Muslim 1/420.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #31 - Supplication at the start of the prayer' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
SELECT r.id, 'ar', 'أخرجه أبو داود، ١/ ٢٠٣، برقم ٧٦٤، وابن ماجه، ١/ ٢٦٥، برقم، ٨٠٧، وأحمد، ٤/ ٨٥، برقم ١٦٧٣٩، وقال شعيب الأرناؤوط في تحقيقه لمسند: ((حسن لغيره))، وقال عبد القادر الأرناؤوط في تخريجه للكلم الطيب لابن تيمية، برقم ٧٨: ((وهو حديث صحيح بشواهده))، وذكره الألباني في صحيح الكلم الطيب، برقم ٦٢، وأخرجه مسلم عن ابن عمر ^ بنحوه، وفيه قصة، ١/ ٤٢٠، برقم ٦٠١.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #31 - Supplication at the start of the prayer' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

