-- 59: item 62
SELECT 'Muslim Data Azkars #62 - After the final tashahhud and before salam', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #62 - After the final tashahhud and before salam' AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُمَّ بِعِلْمِكَ الغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْراً لِي, وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْراً لِي, اللَّهُمَّ إِنِّي أَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ, وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ, وَأَسْأَلُكَ الْقَصْدَ فِي الْغِنَى وَالْفَقْرِ, وَأَسْأَلُكَ نَعِيماً لاَ يَنْفَدُ, وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لاَ تَنْقَطِعُ, وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ, وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ, وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ, وَالشَّوْقَ إِلَى لِقائِكَ فِي غَيرِ ضَرَّاءَ مُضِرَّةٍ, وَلاَ فِتْنَةٍ مُضِلَّةٍ, اللَّهُمَّ زَيِّنَا بِزِينَةِ الإِيمَانِ, وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ');
SELECT r.id, 'ar', 'اللَّهُمَّ بِعِلْمِكَ الغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْراً لِي, وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْراً لِي, اللَّهُمَّ إِنِّي أَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ, وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ, وَأَسْأَلُكَ الْقَصْدَ فِي الْغِنَى وَالْفَقْرِ, وَأَسْأَلُكَ نَعِيماً لاَ يَنْفَدُ, وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لاَ تَنْقَطِعُ, وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ, وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ, وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ, وَالشَّوْقَ إِلَى لِقائِكَ فِي غَيرِ ضَرَّاءَ مُضِرَّةٍ, وَلاَ فِتْنَةٍ مُضِلَّةٍ, اللَّهُمَّ زَيِّنَا بِزِينَةِ الإِيمَانِ, وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #62 - After the final tashahhud and before salam' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُمَّ بِعِلْمِكَ الغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْراً لِي, وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْراً لِي, اللَّهُمَّ إِنِّي أَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ, وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ, وَأَسْأَلُكَ الْقَصْدَ فِي الْغِنَى وَالْفَقْرِ, وَأَسْأَلُكَ نَعِيماً لاَ يَنْفَدُ, وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لاَ تَنْقَطِعُ, وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ, وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ, وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ, وَالشَّوْقَ إِلَى لِقائِكَ فِي غَيرِ ضَرَّاءَ مُضِرَّةٍ, وَلاَ فِتْنَةٍ مُضِلَّةٍ, اللَّهُمَّ زَيِّنَا بِزِينَةِ الإِيمَانِ, وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ');
SELECT r.id, 'en', 'O Allah, by Your Knowledge of the unseen and by Your Power over creation, let me live if You know that life is good for me, and let me die if You know that death is good for me. O Allah, I ask You to grant me fear of You in private and in public. I ask you for the word of truth in times of contentment and anger. I ask You for moderation in wealth and in poverty. I ask you for blessings never ceasing and the coolness of my eye that never ends. I ask You for pleasure after Your Judgment and I ask You for a life of coolness after death. I ask You for the delight of gazing upon Your Face and the joy of meeting You without any harm and misleading trials befalling me. O Allah, dress us with the beauty of Faith, and make us guides who are upon (correct) guidance.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #62 - After the final tashahhud and before salam' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
