SELECT r.id, 'ar', 'النسائي، ٣/ ٥٤، ٥٥، برقم ١٣٠٤، وأحمد، ٤/ ٣٦٤، برقم، ٢١٦٦٦، وصححه الألباني في صحيح النسائي، ١/٢٨١ .' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #62 - After the final tashahhud and before salam' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

