SELECT r.id, 'en', 'O Allah, I ask You, as You are the Owner of praise, there is none worthy of worship but You alone, You have no partner. You are the Giver of all good. O Creator of the heavens and the earth, Owner of majesty and honor. O Living and Everlasting One, I ask you for Paradise and I seek refuge in You from the fire.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #64 - After the final tashahhud and before salam' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
