SELECT 'Muslim Data Azkars #67 - Remembrance after salam', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #67 - Remembrance after salam' AND rt.locale_code = 'ar' AND rt.text = 'لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ, لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ [ثلاثاً], اللَّهُمَّ لاَ مَانِعَ لِمَا أَعْطَيْتَ, وَلاَ مُعْطِيَ لِمَا مَنَعْتَ, وَلاَ يَنْفَعُ ذَا الْجَدِّ مِنْكَ الجَدُّ');
