SELECT r.id, 'en', 'Glory is to Allah, and praise is to Allah, and Allah is the Most Great. (Thirty-Three times each)(1)None has the right to be worshiped but Allah alone, He has no partner, His is the dominion and His is the praise and He is Able to do all things.(2)(Whoever says this after every prayer will be forgiven his sins even though they be as the foam of the sea.)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #69 - Remembrance after salam' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
