SELECT r.id, 'en', 'Allah! There is none worthy of worship but He, the Ever Living, the One Who sustains and protects all that exists. Neither slumber nor sleep overtakes Him. To Him belongs whatever is in the heavens and whatever is on the earth. Who is he that can intercede with Him except with His Permission? He knows what happens to them in this world, and what will happen to them in the Hereafter. And they will never compass anything of His Knowledge except that which He wills. His Throne extends over the heavens and the earth, and He feels no fatigue in guarding and preserving them. And He is the Most High, the Most Great.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #71 - Remembrance after salam' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'An-Nasa''i (Hadith no. 100), Ibn As-Sunni (Hadith no. 121,Sahihul-Jami'' As-Saghir 5/339, Silsilatul al-Ahadith as-Sahihah 2/697.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #71 - Remembrance after salam' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
SELECT r.id, 'ar', 'من قرأها دبر كل صلاة لم يمنعه من دخول الجنة إلا أن يموت. النسائي في عمل اليوم والليلة، برقم ١٠٠، وابن السني، برقم، ١٢١، وصححه الألباني في صحيح الجامع، ٥/٣٣٩، وسلسلة الأحاديث الصحيحة، ٢/٦٩٧، برقم ٩٧٢، والآية رقم ٢٥٥ من سورة البقرة.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #71 - Remembrance after salam' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

