SELECT r.id, 'ar', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْماً نافِعاً, وَرِزْقاً طَيِّباً, وَعَمَلاً مُتَقَبَّلاً (بعد السلام من صلاة الفجر)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #73 - Remembrance after salam' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْماً نافِعاً, وَرِزْقاً طَيِّباً, وَعَمَلاً مُتَقَبَّلاً (بعد السلام من صلاة الفجر)');
SELECT r.id, 'en', 'O Allah, I ask You for knowledge that is of benefit, a good provision, and deeds that will be accepted. (Recite after the Fajr prayer.)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #73 - Remembrance after salam' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
