SELECT r.id, 'ar', 'ابن ماجه، برقم ٩٢٥، والنسائي في عمل اليوم والليلة، برقم ١٠٢، وانظر: صحيح ابن ماجه، ١/١٥٢، ومجمع الزوائد ١٠/١١١، وسيأتي برقم ٩٥.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #73 - Remembrance after salam' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

