SELECT r.id, 'en', 'O Allah, You are my Lord, there is none worthy of worship but You. You created me and I am your slave. I keep Your covenant, and my pledge to You so far as I am able. I seek refuge in You from the evil of what I have done. I admit to Your blessings upon me, and I admit to my misdeeds. Forgive me, for there is none who may forgive sins but You.(Whoever recites it with conviction in the morning and dies during that day shall enter Paradise.)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #79 - Remembrance In the morning' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
