SELECT r.id, 'ar', 'اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لاَ شَرِيكَ لَكَ, فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #81 - Remembrance In the morning' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لاَ شَرِيكَ لَكَ, فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ');
SELECT r.id, 'en', 'O Allah, whatever blessing has been received by me in the morning or anyone of Your creation is from You alone, You have no partner. All praise is for you and thanks is to You. (Whoever recites this in the morning, has completed his obligation to thank Allah for that day.)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #81 - Remembrance In the morning' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
