SELECT r.id, 'ar', 'من قالها حين يصبح فقد أدَّى شكر يومه، ومن قالها حين يمسي فقد أدَّى شكر ليلته. أخرجه أبو داود، ٤/ ٣١٨، برقم ٥٠٧٥، والنسائي في عمل اليوم والليلة، برقم ٧، وابن السني، برقم ٤١، وابن حبان، ((موارد)) برقم ٢٣٦١، وحسّن ابن باز ‘ إسناده في تحفة الأخيار، ص٢٤.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #81 - Remembrance In the morning' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

