SELECT 'Muslim Data Azkars #100 - Remembrance In the evening', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #100 - Remembrance In the evening' AND rt.locale_code = 'ar' AND rt.text = 'أَمسينَا وَأَمسى الْمُلْكُ لِلَّهِ, وَالْحَمْدُ لِلَّهِ, لاَ إِلَهَ إلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ, لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ, رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَه الْليلة وَخَيرَ مَا بَعْدَها, وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَه الْليلة وَشَرِّ مَا بَعْدَها, رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ, رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ');
