SELECT r.id, 'ar', 'اللَّهُمَّ إِنِّي أَمسيتُ أُشْهِدُكَ, وَأُشْهِدُ حَمَلَةَ عَرْشِكَ, وَمَلاَئِكَتِكَ, وَجَمِيعَ خَلْقِكَ, أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلاَّ أَنْتَ وَحْدَكَ لاَ شَرِيكَ لَكَ, وَأَنَّ مُحَمَّداً عَبْدُكَ وَرَسُولُكَ (أربع مرات)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #103 - Remembrance In the evening' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُمَّ إِنِّي أَمسيتُ أُشْهِدُكَ, وَأُشْهِدُ حَمَلَةَ عَرْشِكَ, وَمَلاَئِكَتِكَ, وَجَمِيعَ خَلْقِكَ, أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلاَّ أَنْتَ وَحْدَكَ لاَ شَرِيكَ لَكَ, وَأَنَّ مُحَمَّداً عَبْدُكَ وَرَسُولُكَ (أربع مرات)');
SELECT r.id, 'en', 'O Allah, I have entered the evening and I witness You and witness the bearers of Your Throne, and Your angels and all of Your creation to witness that You are Allah, there is none worthy of worship but You alone, You have no partners, and that Muhammad is Your slave and Your Messenger. (Allah will spare whoever says this four times in the evening from the fire of Hell.)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #103 - Remembrance In the evening' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
