SELECT r.id, 'ar', 'أبو داود، ٤/ ٣٢٢، برقم ٥٠٨٤، وحسن إسناده شعيب وعبد القادر الأرناؤوط في تحقيق زاد المعاد، ٢/٣٧٣ .' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #112 - Remembrance In the evening' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

