SELECT r.id, 'ar', 'أحمد، ٣/ ٤٠٦، و٤٠٧، برقم ١٥٣٦٠، ورقم ١٥٥٦٣، وابن السني في عمل اليوم والليلة، برقم ٣٤، وانظر: صحيح الجامع، ٤/٢٠٩ .' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #113 - Remembrance In the evening' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

