SELECT r.id, 'ar', 'البخاري مع الفتح، ٩/ ٦٢، برقم ٥٠١٧، ومسلم، برقم ٢١٩٢.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #119 - Before sleeping' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

