SELECT r.id, 'ar', '((إذا قام أحدكم من فراشه ثم رجع إليه فلينفضه بصَنِفَةِ إزاره ثلاث مرات، وليُسمِّ اللَّه؛ فإنه لا يدري ما خلفه عليه بعده، وإذا اضطجع فليقل:..)) الحديث، [ومعنى بصَنِفة إزاره: طَرَفه مِمَّا يَلِي طُرَّته]. النهاية في غريب الحديث والأثر (صنف). البخاري مع الفتح، ١١/ ١٢٦، برقم ٦٣٢٠. ومسلم، ٤/ ٢٠٨٤، برقم ٢٧١٤.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #122 - Before sleeping' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

