SELECT r.id, 'en', 'O Allah, I submit myself to You, entrust my affairs to You, turn my face to You, and lay myself down depending upon You, hoping in You and fearing You. There is no refuge, and no escape, except to You. I believe in Your Book (the Qur''an) that You revealed, and the Prophet whom You sent.(Before you go to bed perform ablutions as you would for prayer, then lie down on your right side and says this dua''. Whoever says this and dies in his sleep, has died in a state of the natural monotheism (Fitrah).)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #131 - Before sleeping' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
