SELECT 'Muslim Data Azkars #136 - Qunoot in the Witr prayer', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #136 - Qunoot in the Witr prayer' AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ, وَعَافِنِي فِيمَنْ عَافَيْتَ, وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ, وَبَارِكْ لِي فِيمَا أَعْطَيْتَ, وَقِنِي شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلاَ يُقْضَى عَلَيْكَ, إِنَّهُ لاَ يَذِلُّ مَنْ وَالَيْتَ, [وَلاَ يَعِزُّ مَنْ عَادَيْتَ], تَبارَكْتَ رَبَّنا وَتَعَالَيْتَ');
SELECT r.id, 'ar', 'اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ, وَعَافِنِي فِيمَنْ عَافَيْتَ, وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ, وَبَارِكْ لِي فِيمَا أَعْطَيْتَ, وَقِنِي شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلاَ يُقْضَى عَلَيْكَ, إِنَّهُ لاَ يَذِلُّ مَنْ وَالَيْتَ, [وَلاَ يَعِزُّ مَنْ عَادَيْتَ], تَبارَكْتَ رَبَّنا وَتَعَالَيْتَ' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #136 - Qunoot in the Witr prayer' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ, وَعَافِنِي فِيمَنْ عَافَيْتَ, وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ, وَبَارِكْ لِي فِيمَا أَعْطَيْتَ, وَقِنِي شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلاَ يُقْضَى عَلَيْكَ, إِنَّهُ لاَ يَذِلُّ مَنْ وَالَيْتَ, [وَلاَ يَعِزُّ مَنْ عَادَيْتَ], تَبارَكْتَ رَبَّنا وَتَعَالَيْتَ');
SELECT r.id, 'en', 'O Allah, guide me with those whom You have guided, and strengthen me with those whom You have given strength. Take me to Your care with those whom You have taken to Your care. Bless me in what You have given me. Protect me from the evil You have ordained. Surely, You command and are not commanded, and none whom You have committed to Your care shall be humiliated (and none whom You have taken as an enemy shall taste glory). You are Blessed, Our Lord, and Exalted.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #136 - Qunoot in the Witr prayer' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'Abu Dawud, Ibn Majah, An-Nasa''i, At-Tirmizi, Ahmad, Ad-Darimi, Al-Hakim, Al-Bayhaqi.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #136 - Qunoot in the Witr prayer' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
SELECT r.id, 'ar', 'أخرجه أصحاب السنن الأربعة، وأحمد، والدارمي، والبيهقي: أبو داود، برقم ١٤٢٥، والترمذي، برقم ٤٦٤، والنسائي، برقم ١٧٤٤، وابن ماجه، برقم ١١٧٨، وأحمد، برقم ١٧١٨، والدارمي، برقم ١٥٩٢، والحاكم، ٣/ ١٧٢، والبيهقي، ٢/ ٢٠٩، وما بين المعقوفين للبيهقي، وانظر: صحيح الترمذي، ١/١٤٤، وصحيح ابن ماجه، ١/١٩٤، وإرواء الغليل للألباني، ٢/١٧٢ .' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #136 - Qunoot in the Witr prayer' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

