SELECT r.id, 'en', 'Recitation of the authentic zikr (remembrance of Allah) and the Qur''an. The Devil is driven out by the invocations for morning and evening, zikr before sleeping and upon waking up, zikr for entering and leaving the house, including those for entering and leaving the mosque, and by many other authentic invocations taught to us by the Prophet (SAW) such as the reading of ''Ayatul-Kursi (Al-Baqarah 2:255), and the last two ''ayat of Surat Al-Baqarah and zikr no. 93 100 times, it will be a protection for him from the Devil throughout the day. Also call to prayer (athan).' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #163 - For expelling the devil and his whisperings' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
