SELECT r.id, 'ar', 'قَدَرُ اللَّهُ وَمَا شَاءَ فَعَلَ' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #164 - When stricken with a mishap or overtaken by an affair' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'قَدَرُ اللَّهُ وَمَا شَاءَ فَعَلَ');
SELECT r.id, 'en', 'It is the Decree of Allah and He does whatever He wills.(The strong believer is better and more dear to Allah than the weak believer, and in each of them there is good. Be vigilant for what is to your benefit and seek the help of Allah and do not falter. But when you are stricken by some setback, do not say: "If only I had done such and such..." rather say: "It is the Decree of Allah and He does whatever He wills". For verily the saying ''if...'' begins the work of the Devil.)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #164 - When stricken with a mishap or overtaken by an affair' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'Muslim 4/2052.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #164 - When stricken with a mishap or overtaken by an affair' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
SELECT r.id, 'ar', '((المؤمن القوي خير وأحبّ إلى اللَّه من المؤمن الضعيف، وفي كلٍّ خير، احرص على ما ينفعك، واستعن باللَّهِ ولا تعجز، وإن أصابك شيء فلا تقل: لو أني فعلت كان كذا وكذا، ولكن قل قدَرُ اللَّه وما شاء فعل، فإنَّ لو تفتح عمل الشيطان)). مسلم، ٤/ ٢٠٥٢، برقم ٢٦٦٤.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #164 - When stricken with a mishap or overtaken by an affair' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

