-- 163: item 180
SELECT 'Muslim Data Azkars #180 - For the deceased is a child, during the funeral prayer', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #180 - For the deceased is a child, during the funeral prayer' AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُمَّ أَعِذْهُ مِنْ عَذَابِ القَبْرِ, وإن قال: اللَّهُمَّ اجْعَلْهُ فَرَطاً وَذُخْراً لِوَالِدَيْهِ, وَشَفِيعاً مُجَاباً, اللَّهُمَّ ثَقِّلْ بِهِ مَوَازِينَهُمَا, وَأَعْظِمْ بِهِ أُجورَهُمَا, وَأَلْحِقْهُ بِصَالِحِ الْمُؤْمِنِينَ, وَاجْعَلْهُ فِي كَفَالَةِ إِبْرَاهِيمَ, وَقِهِ بِرَحْمَتِكَ عَذَابَ الْجَحِيمِ, وَأَبْدِلْهُ دَاراً خَيْراً مِنْ دَارِهِ, وَأَهْلاً خَيْراً مِنْ أَهْلِهِ, اللَّهُمَّ اغْفِرْ لِأَسْلاَفِنَا, وَأَفْرَاطِنَا, وَمَنْ سَبَقَنَا بِالْإِيمَانِ (فَحَسَنٌ)');
SELECT r.id, 'ar', 'اللَّهُمَّ أَعِذْهُ مِنْ عَذَابِ القَبْرِ, وإن قال: اللَّهُمَّ اجْعَلْهُ فَرَطاً وَذُخْراً لِوَالِدَيْهِ, وَشَفِيعاً مُجَاباً, اللَّهُمَّ ثَقِّلْ بِهِ مَوَازِينَهُمَا, وَأَعْظِمْ بِهِ أُجورَهُمَا, وَأَلْحِقْهُ بِصَالِحِ الْمُؤْمِنِينَ, وَاجْعَلْهُ فِي كَفَالَةِ إِبْرَاهِيمَ, وَقِهِ بِرَحْمَتِكَ عَذَابَ الْجَحِيمِ, وَأَبْدِلْهُ دَاراً خَيْراً مِنْ دَارِهِ, وَأَهْلاً خَيْراً مِنْ أَهْلِهِ, اللَّهُمَّ اغْفِرْ لِأَسْلاَفِنَا, وَأَفْرَاطِنَا, وَمَنْ سَبَقَنَا بِالْإِيمَانِ (فَحَسَنٌ)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #180 - For the deceased is a child, during the funeral prayer' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُمَّ أَعِذْهُ مِنْ عَذَابِ القَبْرِ, وإن قال: اللَّهُمَّ اجْعَلْهُ فَرَطاً وَذُخْراً لِوَالِدَيْهِ, وَشَفِيعاً مُجَاباً, اللَّهُمَّ ثَقِّلْ بِهِ مَوَازِينَهُمَا, وَأَعْظِمْ بِهِ أُجورَهُمَا, وَأَلْحِقْهُ بِصَالِحِ الْمُؤْمِنِينَ, وَاجْعَلْهُ فِي كَفَالَةِ إِبْرَاهِيمَ, وَقِهِ بِرَحْمَتِكَ عَذَابَ الْجَحِيمِ, وَأَبْدِلْهُ دَاراً خَيْراً مِنْ دَارِهِ, وَأَهْلاً خَيْراً مِنْ أَهْلِهِ, اللَّهُمَّ اغْفِرْ لِأَسْلاَفِنَا, وَأَفْرَاطِنَا, وَمَنْ سَبَقَنَا بِالْإِيمَانِ (فَحَسَنٌ)');
SELECT r.id, 'en', 'O Allah, protect him from the torment of the grave.(1)O Allah, make him a precursor, a forerunner and a treasure for his parents and an answered intercessor. O Allah, make him weigh heavily in their scales (of good) and magnify their reward. Make him join the righteous of the believers. Place him in the care of Ibrahim. Save him by Your mercy from the torment of Hell. Give him a home better than his home and a family better than his family. O Allah, forgive those who have gone before us, our children lost (by death), and those who have preceded us in Faith.(2)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #180 - For the deceased is a child, during the funeral prayer' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'Ibn Qudamah, Al-Mughni 3/416.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #180 - For the deceased is a child, during the funeral prayer' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
SELECT r.id, 'ar', '((قال سعيد بن المسيب: صلّيتُ وراء أبي هريرة على صبيٍّ لم يعمل خطيئة قَطُّ، فسمعته يقول..)) الحديث. أخرجه مالك في الموطأ، ١/٢٨٨، وابن أبي شيبة في المصنف، ٣/٢١٧، والبيهقي، ٤/٩، وصحح إسناده شعيب الأرناؤوط في تحقيقه لشرح السنة للبغوي، ٥/٣٥٧ . انظر: المغني لابن قدامة، ٣/٤١٦، والدروس المهمة لعامة الأمة، للشيخ عبد العزيز بن عبد الله بن باز ‘، ص١٥ .' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #180 - For the deceased is a child, during the funeral prayer' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

