SELECT 'Muslim Data Azkars #211 - On the wedding night or when buying an animal', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #211 - On the wedding night or when buying an animal' AND rt.locale_code = 'ar' AND rt.text = 'إِذَا تَزَوَّجَ أَحَدُكُمُ امْرَأَةً, أَوْ إِذَا اشْتَرَى خَادِماً فَلْيَقُلْ: اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا, وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ, وَأَعُوذُ بِكَ مِنْ شَرِّهَا, وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ, وَإِذَا اشْتَرَى بَعِيراً فَلْيَأْخُذْ بِذِرْوَةِ سَنَامِهِ وَلْيَقُلْ مِثْلَ ذَلِكَ');
SELECT r.id, 'ar', 'إِذَا تَزَوَّجَ أَحَدُكُمُ امْرَأَةً, أَوْ إِذَا اشْتَرَى خَادِماً فَلْيَقُلْ: اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا, وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ, وَأَعُوذُ بِكَ مِنْ شَرِّهَا, وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ, وَإِذَا اشْتَرَى بَعِيراً فَلْيَأْخُذْ بِذِرْوَةِ سَنَامِهِ وَلْيَقُلْ مِثْلَ ذَلِكَ' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #211 - On the wedding night or when buying an animal' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'إِذَا تَزَوَّجَ أَحَدُكُمُ امْرَأَةً, أَوْ إِذَا اشْتَرَى خَادِماً فَلْيَقُلْ: اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا, وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ, وَأَعُوذُ بِكَ مِنْ شَرِّهَا, وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ, وَإِذَا اشْتَرَى بَعِيراً فَلْيَأْخُذْ بِذِرْوَةِ سَنَامِهِ وَلْيَقُلْ مِثْلَ ذَلِكَ');
SELECT r.id, 'en', 'When any of you marries a woman or purchases a maid-servant then let him say: "O Allah, I ask You for the goodness of her and the goodness upon which You have created her, and I seek refuge in You from the evil of her and from the evil upon which You have created her". If you purchase a camel (animal) then take hold of the top of its hump and say the same.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #211 - On the wedding night or when buying an animal' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
