SELECT 'Muslim Data Azkars #227 - For travel', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #227 - For travel' AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُ أَكْبَرُ, اللَّهُ أَكْبَرُ, اللَّهُ أَكْبَرُ, سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ * وَإِنَّا إِلَى رَبِّنَا لَمُنقَلِبُونَ, (اللَّهُمَّ إِنّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا البِرَّ وَالتَّقْوَى, وَمِنَ الْعَمَلِ مَا تَرْضَى, اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ, اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ, وَالْخَليفَةُ فِي الْأَهْلِ, اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ, وَكَآبَةِ الْمَنْظَرِ, وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالْأَهْلِ), وإذا رَجَعَ قَالَهُنَّ وَزَادَ فِيهِنَّ: (آيِبُونَ, تائِبُونَ, عَابِدُونَ, لِرَبِّنَا حَامِدُونَ)');
SELECT r.id, 'ar', 'اللَّهُ أَكْبَرُ, اللَّهُ أَكْبَرُ, اللَّهُ أَكْبَرُ, سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ * وَإِنَّا إِلَى رَبِّنَا لَمُنقَلِبُونَ, (اللَّهُمَّ إِنّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا البِرَّ وَالتَّقْوَى, وَمِنَ الْعَمَلِ مَا تَرْضَى, اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ, اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ, وَالْخَليفَةُ فِي الْأَهْلِ, اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ, وَكَآبَةِ الْمَنْظَرِ, وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالْأَهْلِ), وإذا رَجَعَ قَالَهُنَّ وَزَادَ فِيهِنَّ: (آيِبُونَ, تائِبُونَ, عَابِدُونَ, لِرَبِّنَا حَامِدُونَ)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #227 - For travel' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُ أَكْبَرُ, اللَّهُ أَكْبَرُ, اللَّهُ أَكْبَرُ, سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ * وَإِنَّا إِلَى رَبِّنَا لَمُنقَلِبُونَ, (اللَّهُمَّ إِنّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا البِرَّ وَالتَّقْوَى, وَمِنَ الْعَمَلِ مَا تَرْضَى, اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ, اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ, وَالْخَليفَةُ فِي الْأَهْلِ, اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ, وَكَآبَةِ الْمَنْظَرِ, وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالْأَهْلِ), وإذا رَجَعَ قَالَهُنَّ وَزَادَ فِيهِنَّ: (آيِبُونَ, تائِبُونَ, عَابِدُونَ, لِرَبِّنَا حَامِدُونَ)');
SELECT r.id, 'en', 'Allah is the Most Great. Allah is the Most Great. Allah is the Most Great. Glory is to Him Who has provided this for us though we could never have had it by our efforts. Surely, unto our Lord we are returning. O Allah, we ask You on this our journey for goodness and piety, and for works that are pleasing to You. O Allah , lighten this journey for us and make its distance easy for us. O Allah, You are our Companion on the road and the One in Whose care we leave our family. O Allah, I seek refuge in You from this journey''s hardships, and from the wicked sights in store and from finding our family and property in misfortune upon returning.(1)Upon returning recite the same and adding: "We return repentant to our Lord, worshiping our Lord, and praising our Lord".(2)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #227 - For travel' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'Muslim 2/978.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #227 - For travel' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
SELECT r.id, 'ar', 'مسلم، ٢/ ٩٧٨، برقم ١٣٤٢.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #227 - For travel' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

