SELECT 'Muslim Data Azkars #228 - Upon entering a town or village', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #228 - Upon entering a town or village' AND rt.locale_code = 'ar' AND rt.text = 'اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَمَا أَظْلَلْنَ, وَرَبَّ الأَرَضِينَ السَّبْعِ وَمَا أَقْلَلْنَ, وَرَبَّ الشَّياطِينِ وَمَا أَضْلَلْنَ, وَرَبَّ الرِّيَاحِ وَمَا ذَرَيْنَ, أَسْأَلُكَ خَيْرَ هَذِهِ الْقَرْيَةِ, وَخَيْرَ أَهْلِهَا, وَخَيْرَ مَا فِيهَا, وَأَعُوذُ بِكَ مِنْ شَرِّهَا, وَشَرِّ أَهْلِهَا, وَشَرِّ مَا فِيهَا');
