SELECT r.id, 'en', 'O Allah, Lord of the Seven heavens and all they overshadow, Lord of the Seven worlds and all they uphold, Lord of the devils and all they lead astray, Lord of the winds and all they scatter. I ask You for the goodness of this town and for the goodness of its people, and for the goodness it contains. I seek refuge in You from its evil, from the evil of its people and from the evil it contains.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #228 - Upon entering a town or village' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
