SELECT r.id, 'ar', 'الحاكم وصححه ووافقه الذهبي، ٢/١٠٠، وابن السني، برقم ٥٢٤، وحسّنه الحافظ في تخريج الأذكار، ٥/١٥٤، قال العلامة ابن باز ‘: ((ورواه النسائي بإسناد حسن)). انظر: تحفة الأخيار، ص٣٧.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #228 - Upon entering a town or village' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

