SELECT r.id, 'en', 'None has the right to be worshiped but Allah alone, Who has no partner. His is the dominion and His is the praise. He brings life and He causes death, and He is living and does not die. In His Hand is all good, and He is Able to do all things.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #229 - When entering the market' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
