-- 239: item 256
SELECT 'Muslim Data Azkars #256 - When at Mount Safa and Mount Marwah', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #256 - When at Mount Safa and Mount Marwah' AND rt.locale_code = 'ar' AND rt.text = 'لَمَّا دَنَا النَّبِيُّ صلى الله عليه وسلم مِنَ الصَّفَا قَرَأَ: ﴿إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَآئِرِ اللَّهِ﴾ أَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ فَبَدَأَ بِالصَّفَا فَرَقِيَ عَلَيْهِ حَتَّى رَأَى الْبَيْتَ, فَاسْتَقْبَلَ الْقِبْلَةَ, فَوَحَّدَ اللَّهَ وَكبَّرَهُ وَقَالَ: (لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ, لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ, لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ, أَنْجَزَ وَعْدَهُ, وَنَصَرَ عَبْدَهُ, وَهَزَمَ الْأَحْزَابَ وَحْدَهُ, ثُمَّ دَعَا بَيْنَ ذلكَ. قَالَ مِثْلَ هَذَا ثَلاَثَ مَرَّاتٍ) الْحَدِيثُ. وَفِيهِ: (فَفَعَلَ عَلَى الْمَرْوَةِ كَمَا فَعَلَ عَلَى الصَّفَا)');
SELECT r.id, 'ar', 'لَمَّا دَنَا النَّبِيُّ صلى الله عليه وسلم مِنَ الصَّفَا قَرَأَ: ﴿إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَآئِرِ اللَّهِ﴾ أَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ فَبَدَأَ بِالصَّفَا فَرَقِيَ عَلَيْهِ حَتَّى رَأَى الْبَيْتَ, فَاسْتَقْبَلَ الْقِبْلَةَ, فَوَحَّدَ اللَّهَ وَكبَّرَهُ وَقَالَ: (لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ, لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ, لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ, أَنْجَزَ وَعْدَهُ, وَنَصَرَ عَبْدَهُ, وَهَزَمَ الْأَحْزَابَ وَحْدَهُ, ثُمَّ دَعَا بَيْنَ ذلكَ. قَالَ مِثْلَ هَذَا ثَلاَثَ مَرَّاتٍ) الْحَدِيثُ. وَفِيهِ: (فَفَعَلَ عَلَى الْمَرْوَةِ كَمَا فَعَلَ عَلَى الصَّفَا)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #256 - When at Mount Safa and Mount Marwah' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'لَمَّا دَنَا النَّبِيُّ صلى الله عليه وسلم مِنَ الصَّفَا قَرَأَ: ﴿إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَآئِرِ اللَّهِ﴾ أَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ فَبَدَأَ بِالصَّفَا فَرَقِيَ عَلَيْهِ حَتَّى رَأَى الْبَيْتَ, فَاسْتَقْبَلَ الْقِبْلَةَ, فَوَحَّدَ اللَّهَ وَكبَّرَهُ وَقَالَ: (لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ, لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ, لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ, أَنْجَزَ وَعْدَهُ, وَنَصَرَ عَبْدَهُ, وَهَزَمَ الْأَحْزَابَ وَحْدَهُ, ثُمَّ دَعَا بَيْنَ ذلكَ. قَالَ مِثْلَ هَذَا ثَلاَثَ مَرَّاتٍ) الْحَدِيثُ. وَفِيهِ: (فَفَعَلَ عَلَى الْمَرْوَةِ كَمَا فَعَلَ عَلَى الصَّفَا)');
SELECT r.id, 'en', 'Whenever the Prophet (SAW) approached Mount Safa, he would recite: "Surely Safa and Marwah are among the signs of Allah. I begin by that which Allah began".(1) Then he began (his Sa''y) at Mount Safa climbing it until he could see the House (Kaaba). He then faced the Qiblah repeating the words: "Allah is the Most Great, Allah is the Most Great, Allah is the Most Great".(2) Then he said: "None has the right to be worshiped but Allah alone, Who has no partner, His is the dominion and His is the praise, and He is Able to do all things. None has the right to be worshiped but Allah alone, He fulfilled His Promise, He aided His slave, and He alone defeated Confederates".(3) Then he would ask Allah for what he liked, repeating the same thing like this Three times. He did at Mount Marwah as he did at Mount Safa.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #256 - When at Mount Safa and Mount Marwah' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'Muslim 2/888.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #256 - When at Mount Safa and Mount Marwah' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
SELECT r.id, 'ar', 'مسلم، ٢/ ٨٨٨، برقم ١٢١٨،والآية من سورة البقرة، رقم ١٥٨.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #256 - When at Mount Safa and Mount Marwah' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

