SELECT r.id, 'ar', 'الترمذي، برقم ٣٥٨٥، وحسنه الألباني في صحيح الترمذي، ٣/١٨٤، وفي سلسلة الأحاديث الصحيحة، ٤/٦ .' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #257 - The Day of ''Arafah' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

