SELECT 'Muslim Data Azkars #258 - Remembrance at Muzdalifa', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #258 - Remembrance at Muzdalifa' AND rt.locale_code = 'ar' AND rt.text = 'رَكِبَ النَّبِيُّ صلى الله عليه وسلم الْقَصْوَاءَ حَتَّى أَتَى الْمَشْعَرَ الْحَرَامَ فَاسْتَقْبَلَ الْقِبْلَةَ (فَدَعَاهُ, وَكَبَّرَهُ, وَهَللَّهُ, وَوَحَّدَهُ) فَلَمْ يَزَلْ وَاقِفاً حَتَّى أَسْفَرَ جِدَّاً فَدَفَعَ قَبْلَ أَنْ تَطْلُعَ الشَّمسُ');
SELECT r.id, 'ar', 'رَكِبَ النَّبِيُّ صلى الله عليه وسلم الْقَصْوَاءَ حَتَّى أَتَى الْمَشْعَرَ الْحَرَامَ فَاسْتَقْبَلَ الْقِبْلَةَ (فَدَعَاهُ, وَكَبَّرَهُ, وَهَللَّهُ, وَوَحَّدَهُ) فَلَمْ يَزَلْ وَاقِفاً حَتَّى أَسْفَرَ جِدَّاً فَدَفَعَ قَبْلَ أَنْ تَطْلُعَ الشَّمسُ' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #258 - Remembrance at Muzdalifa' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'رَكِبَ النَّبِيُّ صلى الله عليه وسلم الْقَصْوَاءَ حَتَّى أَتَى الْمَشْعَرَ الْحَرَامَ فَاسْتَقْبَلَ الْقِبْلَةَ (فَدَعَاهُ, وَكَبَّرَهُ, وَهَللَّهُ, وَوَحَّدَهُ) فَلَمْ يَزَلْ وَاقِفاً حَتَّى أَسْفَرَ جِدَّاً فَدَفَعَ قَبْلَ أَنْ تَطْلُعَ الشَّمسُ');
SELECT r.id, 'en', 'The Prophet (SAW) rode his camel, Al-Qaswa'' (from Arafah), until he reached the sacred area (Al-Mash''aril-Haraam). Then he faced the Qiblah and invoked Allah, and repeatedly said:"Allah is the Most Great",(1)"There is none worthy of worship but Allah"(2) and"Allah is One".(3)He remained stationary until the sky became yellow with the dawn, and then pressed on before sunrise.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #258 - Remembrance at Muzdalifa' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'Muslim 2/891.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #258 - Remembrance at Muzdalifa' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
SELECT r.id, 'ar', 'مسلم، ٢/ ٨٩١، برقم ١٢١٨.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #258 - Remembrance at Muzdalifa' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

