SELECT 'Muslim Data Azkars #259 - When throwing each pebble at the Jamarat', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #259 - When throwing each pebble at the Jamarat' AND rt.locale_code = 'ar' AND rt.text = 'يُكَبِّرُ كُلَّمَا رَمَى بِحَصَاةٍ عِنْدَ الْجِمَارِ الثَّلاَثِ, ثُمَّ يَتَقَدَّمُ, ويَقِفُ يَدْعُو مُسْتَقْبِلَ الْقِبلَةِ, رَافِعاً يَدَيْهِ بَعْدَ الْجَمْرَةِ الْأُولَى وَالثَّانِيَةِ. أَمَّا جَمْرَةُ الْعَقَبَةِ فَيَرْمِيهَا وَيُكَبِّرُ عِنْدَ كُلِّ حَصَاةٍ وَيَنْصَرِفُ وَلاَ يَقِفُ عِنْدَهَا');
SELECT r.id, 'ar', 'يُكَبِّرُ كُلَّمَا رَمَى بِحَصَاةٍ عِنْدَ الْجِمَارِ الثَّلاَثِ, ثُمَّ يَتَقَدَّمُ, ويَقِفُ يَدْعُو مُسْتَقْبِلَ الْقِبلَةِ, رَافِعاً يَدَيْهِ بَعْدَ الْجَمْرَةِ الْأُولَى وَالثَّانِيَةِ. أَمَّا جَمْرَةُ الْعَقَبَةِ فَيَرْمِيهَا وَيُكَبِّرُ عِنْدَ كُلِّ حَصَاةٍ وَيَنْصَرِفُ وَلاَ يَقِفُ عِنْدَهَا' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #259 - When throwing each pebble at the Jamarat' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'يُكَبِّرُ كُلَّمَا رَمَى بِحَصَاةٍ عِنْدَ الْجِمَارِ الثَّلاَثِ, ثُمَّ يَتَقَدَّمُ, ويَقِفُ يَدْعُو مُسْتَقْبِلَ الْقِبلَةِ, رَافِعاً يَدَيْهِ بَعْدَ الْجَمْرَةِ الْأُولَى وَالثَّانِيَةِ. أَمَّا جَمْرَةُ الْعَقَبَةِ فَيَرْمِيهَا وَيُكَبِّرُ عِنْدَ كُلِّ حَصَاةٍ وَيَنْصَرِفُ وَلاَ يَقِفُ عِنْدَهَا');
SELECT r.id, 'en', 'The Prophet (SAW) said Allaahu ''Akbar (Allah is the Most Great) with each pebble he threw at the Three pillars. Then he went forward, stood facing the Qiblah and raised his hands and called upon Allah. That was after (stoning) the first and second pillar. As for the third, he stoned it and called out Allaahu ''Akbar with every pebble he threw, but when he was finished he left without standing at it (for supplications).' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #259 - When throwing each pebble at the Jamarat' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'Al-Bukhari, Muslim' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #259 - When throwing each pebble at the Jamarat' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
SELECT r.id, 'ar', 'البخاري مع الفتح، ٣/ ٥٨٣، برقم ١٧٥١، وانظر لفظه هناك. والبخاري مع الفتح، ٣/ ٥٨٣، و٣/ ٥٨٤، و٣/ ٥٨١، برقم ١٧٥٣، ورواه مسلم أيضاً، برقم ١٢١٨.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #259 - When throwing each pebble at the Jamarat' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

