-- 265: item 282
SELECT 'Muslim Data Azkars #282 - Excellence of remembrance and glorification of Allah', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #282 - Excellence of remembrance and glorification of Allah' AND rt.locale_code = 'ar' AND rt.text = 'جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ: عَلِّمْنِي كَلاماً أَقُولُهُ: قَالَ: (قُلْ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ, اللَّهُ أَكْبَرُ كَبِيراً, وَالْحَمْدُ لِلَّهِ كَثِيراً, سُبْحَانَ اللَّهِ رَبِّ العَالَمِينَ, لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ الْعَزِيزِ الْحَكِيمِ) قَالَ: فَهَؤُلاَءِ لِرَبِّي, فَمَا لِي؟ قَالَ: (قُلْ: اللَّهُمَّ اغْفِرْ لِي, وَارْحَمْنِي, وَاهْدِنِي, وَارْزُقْنِي)');
SELECT r.id, 'ar', 'جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ: عَلِّمْنِي كَلاماً أَقُولُهُ: قَالَ: (قُلْ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ, اللَّهُ أَكْبَرُ كَبِيراً, وَالْحَمْدُ لِلَّهِ كَثِيراً, سُبْحَانَ اللَّهِ رَبِّ العَالَمِينَ, لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ الْعَزِيزِ الْحَكِيمِ) قَالَ: فَهَؤُلاَءِ لِرَبِّي, فَمَا لِي؟ قَالَ: (قُلْ: اللَّهُمَّ اغْفِرْ لِي, وَارْحَمْنِي, وَاهْدِنِي, وَارْزُقْنِي)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #282 - Excellence of remembrance and glorification of Allah' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ: عَلِّمْنِي كَلاماً أَقُولُهُ: قَالَ: (قُلْ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ, اللَّهُ أَكْبَرُ كَبِيراً, وَالْحَمْدُ لِلَّهِ كَثِيراً, سُبْحَانَ اللَّهِ رَبِّ العَالَمِينَ, لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ الْعَزِيزِ الْحَكِيمِ) قَالَ: فَهَؤُلاَءِ لِرَبِّي, فَمَا لِي؟ قَالَ: (قُلْ: اللَّهُمَّ اغْفِرْ لِي, وَارْحَمْنِي, وَاهْدِنِي, وَارْزُقْنِي)');
SELECT r.id, 'en', 'A desert Arab came to Allah''s Messenger (SAW) and said: "Teach me a word that I can say". The Prophet told him to say: "There is none worthy of worship but Allah, Who has no partner, Allah is the Great, the Most Great, and praise is to Allah in abundance, glory is to Allah, Lord of the worlds. There is no power and no might but by Allah the Mighty, the Wise". (1) He said: "That is for my Lord, but what about me?" The Prophet (SAW) told him to say: "O Allah forgive me, and have mercy on me and guide me, and provide for me". (2)' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #282 - Excellence of remembrance and glorification of Allah' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'Muslim 4/2072.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #282 - Excellence of remembrance and glorification of Allah' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
SELECT r.id, 'ar', 'مسلم، ٤/ ٢٠٧٢، برقم ٢٦٩٦، وزاد أبو داود، ١/ ٢٢٠، برقم ٨٣٢: فلما ولّى الأعرابي قال النبي صلى الله عليه وسلم: ((لقد ملأ يده من الخير)).' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #282 - Excellence of remembrance and glorification of Allah' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

