SELECT 'Muslim Data Azkars #283 - Excellence of remembrance and glorification of Allah', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #283 - Excellence of remembrance and glorification of Allah' AND rt.locale_code = 'ar' AND rt.text = 'كَانَ الرَّجُلُ إِذَا أَسْلَمَ عَلَّمَهُ النَّبيُّ صلى الله عليه وسلم الصَّلاَةَ ثُمَّ أَمَرَهُ أَنْ يَدْعُوَ بِهَؤُلاَءِ الْكَلِمَاتِ: اللَّهُمَّ اغْفِرِ لِي, وَارْحَمْنِي, وَاهْدِنِي, وَعَافِنِي وَارْزُقْنِي');
