SELECT r.id, 'ar', 'أحمد، برقم ٥١٣، بترتيب أحمد شاكر، وانظر: مجمع الزوائد، ١/٢٩٧، وعزاه ابن حجر في بلوغ المرام من رواية أبي سعيد إلى النسائي [في الكبرى]، برقم ١٠٦١٧، وقال: صححه ابن حبان، [برقم ٨٤٠]، والحاكم [١/ ٥٤١].' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #285 - Excellence of remembrance and glorification of Allah' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');

