-- 269: item 286
SELECT 'Muslim Data Azkars #286 - How the Prophet made Tasbeeh', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #286 - How the Prophet made Tasbeeh' AND rt.locale_code = 'ar' AND rt.text = 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رضي الله عنهما قَالَ: (رَأَيْتُ النَّبيَّ صلى الله عليه وسلم يَعْقِدُ التَّسْبِيحَ) وفي زيادةٍ: (بِيَمِينِهِ)');
