-- -----------------------------------------------------------------------------
-- 270: item 287
SELECT 'Muslim Data Azkars #287 - General and beneficent rules', 'UNSPECIFIED' WHERE NOT EXISTS (SELECT 1 FROM remembrance r JOIN remembrance_translation rt ON rt.remembrance_id = r.id WHERE r.source = 'Muslim Data Azkars #287 - General and beneficent rules' AND rt.locale_code = 'ar' AND rt.text = 'قَالَ النَّبِيُّ صلى الله عليه وسلم: إِذَا كَانَ جُنْحُ اللَّيْلِ – أَوْ أَمْسَيْتُم – فَكُفُّوا صِبْيانَكُم, فَإِنَّ الشَّيَاطِينَ تَنْتَشِرُ حِينَئِذٍ, فَإِذَا ذَهَبَ سَاعَةٌ مِنَ اللَّيلِ فَخَلُّوهُمْ, وَأَغْلِقُوا الأَبْوَابَ وَاذْكُرُوا اسْمَ اللَّهِ؛ فَإِنَّ الشَّيطَانَ لاَ يَفْتَحُ بَاباً مُغلَقاً, وَأَوْكُوا قِرَبَكُمْ, وَاذْكُرُوا اسْمَ اللَّهِ, وَخَمِّرُوا آنِيَتَكُم, وَاذْكُرُوا اسْمَ اللَّهِ, وَلَوْ أَنْ تَعْرُضُوا عَلَيْهَا شَيْئاً, وَأَطْفِئُوا مَصَابِيحَكُمْ');
SELECT r.id, 'ar', 'قَالَ النَّبِيُّ صلى الله عليه وسلم: إِذَا كَانَ جُنْحُ اللَّيْلِ – أَوْ أَمْسَيْتُم – فَكُفُّوا صِبْيانَكُم, فَإِنَّ الشَّيَاطِينَ تَنْتَشِرُ حِينَئِذٍ, فَإِذَا ذَهَبَ سَاعَةٌ مِنَ اللَّيلِ فَخَلُّوهُمْ, وَأَغْلِقُوا الأَبْوَابَ وَاذْكُرُوا اسْمَ اللَّهِ؛ فَإِنَّ الشَّيطَانَ لاَ يَفْتَحُ بَاباً مُغلَقاً, وَأَوْكُوا قِرَبَكُمْ, وَاذْكُرُوا اسْمَ اللَّهِ, وَخَمِّرُوا آنِيَتَكُم, وَاذْكُرُوا اسْمَ اللَّهِ, وَلَوْ أَنْ تَعْرُضُوا عَلَيْهَا شَيْئاً, وَأَطْفِئُوا مَصَابِيحَكُمْ' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #287 - General and beneficent rules' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'ar' AND rt.text = 'قَالَ النَّبِيُّ صلى الله عليه وسلم: إِذَا كَانَ جُنْحُ اللَّيْلِ – أَوْ أَمْسَيْتُم – فَكُفُّوا صِبْيانَكُم, فَإِنَّ الشَّيَاطِينَ تَنْتَشِرُ حِينَئِذٍ, فَإِذَا ذَهَبَ سَاعَةٌ مِنَ اللَّيلِ فَخَلُّوهُمْ, وَأَغْلِقُوا الأَبْوَابَ وَاذْكُرُوا اسْمَ اللَّهِ؛ فَإِنَّ الشَّيطَانَ لاَ يَفْتَحُ بَاباً مُغلَقاً, وَأَوْكُوا قِرَبَكُمْ, وَاذْكُرُوا اسْمَ اللَّهِ, وَخَمِّرُوا آنِيَتَكُم, وَاذْكُرُوا اسْمَ اللَّهِ, وَلَوْ أَنْ تَعْرُضُوا عَلَيْهَا شَيْئاً, وَأَطْفِئُوا مَصَابِيحَكُمْ');
SELECT r.id, 'en', 'When evening descends, bring your children indoors for the devils scatter out at this hour. Then after the passing of an hour (the first hour) of the night, (you may) let them (the children) go. Close your doors while mentioning the Name of Allah, for the devil may not open a closed door. Fasten your waterskins mentioning the Name of Allah. Cover your eating vessels mentioning the Name of Allah even if you just put something over it, and extinguish your lamps.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #287 - General and beneficent rules' AND NOT EXISTS (SELECT 1 FROM remembrance_translation rt WHERE rt.remembrance_id = r.id AND rt.locale_code = 'en');
SELECT r.id, 'en', 'Al-Bukhari, Muslim 3/1595.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #287 - General and beneficent rules' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'en');
SELECT r.id, 'ar', 'البخاري مع الفتح، ١٠/ ٨٨، برقم ٥٦٢٣، ومسلم، ٣/ ١٥٩٥، برقم ٢٠١٢.' FROM remembrance r WHERE r.source = 'Muslim Data Azkars #287 - General and beneficent rules' AND NOT EXISTS (SELECT 1 FROM explanation_translation et WHERE et.remembrance_id = r.id AND et.locale_code = 'ar');
